    def certificate_configure(self, **kwargs):
        """ This keyword is used to configure or get certificate details.
            Multiple operations are supported in same keyword.

        Supported operations :
            initialize_cmp_certificate,
            update_certificate_revocation_list,
            restore_vendor_certificate,
            get_certificate_list,
            get_certificate_details,
            get_certificate_revocation_list,
            get_certificate_file,
            install_certificate,
            set_certificate_automatic_managment,
            cmp_update_key,
            delete_cert

        | *Arguments* | *Default* | *Comments* |
        | operation | '' | Operation from the above list |
        | cert_file | Mandatory for 'Install Certificate' operation | The certificate file to be
            installed |
        | cert_type | Mandatory for 'Install Certificate' operation | Can be btsTrustChain or
            additionalCa |
        | cert_format | Mandatory for 'Install Certificate' operation | Can be PEM, P12 or DER |
        | password | Optional for 'Install Certificate' operation | Can be None or the Certificate
            password |
        | type | Mandatory for 'get_certificate_list' operation. Can be BTS, TA, CA, RA, Vendor or
            All | | Optional for 'get_certificate_details' operation. Can be None, EndEntity, CA,
            or TrustAnchor | | Optional for 'get_certificate_file' operation. Can be None,
            EndEntity, CA, or TrustAnchor | | Optional for 'delete_certificate' operation. Can be
            None, EndEntity, CA, or TrustAnchor |
        | Subject | Optional for 'get_certificate_file', 'get_certificate_details' or
            'delete_certificate' operations. |
        | Source | Mandatory for 'get_certificate_file', 'get_certificate_details' or
            'delete_certificate' operations. Can be 'Operator' or 'Vendor' |
        | all_certs | Optional for 'delete_certificate'. Default False | Deletes all certificates
            if True |
        | domain_type | Optional for get_certificate_revocation_list and update_certificate_revocation_list.Default 3GPP . Can be 3GPP or CBRS | Get certificate revocation list |
        | timeout | Optional argument | Default value is 60 seconds | Timeout for the operation |
        | alias | Optional argument | Default value is 'default' | Name of the execution context |


        *Examples:*

        *Get Certificate Details *
        | Certificate Configure | operation=get_certificate_details |
            subject=L1162615178.nokiasolutionsandnetworks.com| type=EndEntity | source=Vendor |
        """

        return Certificate().certificate_configure(**kwargs)

