    def get_parent_distnames_of_a_parameter(self, **kwargs):
        """
            Gets all the distnames, the given parameter belongs to.

         *Usage*:
        Get Parent Distnames Of A Parameter     <param_name>    <param_val>   <scf_file>    <alias>
        | *arguments* | *comment* | *default value* |
        | *param_name* | The param name to be searched | |
        | *param_value* | The param value to be searched | |
        | *scf_file* | The scf_file name which should be used for searching. If none the scf passed
            with pybot will be considered. | None |
        | *alias* | Name of execution context. | default |
        | rat | At least one of the RATs is Mandatory eg. lte/wcdma/gsm etc. | common |

        *Example*
        | *keyword* | *param_name* | *param_val* | *scf_file* | *alias* |
        | Get Parent Distnames Of A Parameter | param_name=committedBitRate | param_val=999900 |
        | Get Parent Distnames Of A Parameter | param_name=committedBitRate | param_val=999900 |
            scf_file=1ip_scf.xml | alias=conn1 |
        """

        scf_file = kwargs.get("scf_file", None)
        alias = kwargs.get("alias", 'default')
        bts_id, scf_file = AdminBaseClass().get_scf_full_path(scf_file, alias)
        scf_parser = ScfParser(scf_file)
        return scf_parser.get_distname_from_parameter_by_iteration(**kwargs)

